	private static NativeGroupIteration typedProofIteration(Fixture fixture, SlotPlan input, AggregateSpec[] specs) {
		return new NativeGroupIteration(fixture.source, input, fixture.layout, new int[] { 0 }, specs, false,
				EmptyBindingSet.getInstance(), null, null, false, null);
	}

	private static LmdbNativeStrategyProposal<NativeResultCursor> typedProofProposal(Fixture fixture,
			NativeGroupIteration iteration, RowState row, NativeGroupResultCursor.GroupingPlan plan) {
		LmdbNativeStrategyProposal<NativeResultCursor> proposal = new LmdbNativeStrategyProposal<>(
				() -> plan.open(iteration, fixture.source.executionContext()),
				plan.input().estimateWork(row, row.boundMask()),
				plan.tag(), () -> {
				});
		proposal.withAggregatePhysicalPlan(NativeAggregatePhysicalPlan.typed(plan, iteration));
		return new NativeAggregateCostQuotes(iteration, row, null, false).attach(proposal);
	}

	private static Map<String, Long> fullUnicodeGroupLengths(Fixture fixture) throws Exception {
		AggregateSpec[] full = { AggregateSpec.groupConcat("length", 1, true, "|") };
		Map<String, Long> result = new HashMap<>();
		try (NativeGroupIteration iteration = iteration(fixture, null, full, null);
				NativeResultCursor rows = NativeGroupResultCursor.tablePlan(iteration)
						.open(iteration, fixture.source.executionContext())) {
			NativeResultRow row;
			while ((row = rows.next()) != null) {
				assertEquals(NativeResultCell.Kind.RDF_TERM, row.cell("length").kind());
				String text = row.cell("length").value().stringValue();
				assertEquals("\ud83d\ude00\u03bb|x", text, "FULL retains the independent Unicode lexical identity");
				result.put(row.cell("group").value().stringValue(), (long) text.codePointCount(0, text.length()));
			}
		}
		assertEquals(FIXTURE_GROUPS, result.size());
		return result;
	}

	private static Map<String, Long> summaryGroupLengths(NativeResultCursor rows) {
		Map<String, Long> result = new HashMap<>();
		try (rows) {
			NativeResultRow row;
			while ((row = rows.next()) != null) {
				assertEquals(NativeResultCell.Kind.LEXICAL_SUMMARY, row.cell("length").kind());
				result.put(row.cell("group").value().stringValue(), row.cell("length").codePointLength());
			}
		}
		return result;
	}

	@Test
	void fallbackIndexNameCannotCertifyTheOpenedEncounterOrder() throws Exception {
		assertAll("only an order bound to the opened producer may prove contiguous groups",
				() -> assertImplicitFallbackOrderIsUnknown(
						new AggregateSpec[] { AggregateSpec.groupConcat("text", 1, false, "|") }, false,
						"FULL GROUP_CONCAT"),
				() -> assertImplicitFallbackOrderIsUnknown(new AggregateSpec[] {
						AggregateSpec.slot("count", 1, true, AggKind.COUNT),
						AggregateSpec.slot("sum", 1, false, AggKind.SUM) }, true,
						"floating COUNT(DISTINCT) and SUM"),
				() -> assertExplicitOrderStillProvesGroupedInput());
	}

	private static void assertImplicitFallbackOrderIsUnknown(AggregateSpec[] specs, boolean distinctChannel,
			String aggregateName) throws Exception {
		try (Fixture fixture = implicitOrderMismatchFixture(2, 4, distinctChannel)) {
			NativeGroupIteration iteration = iteration(fixture, null, specs, null);
			RowState row = new RowState(fixture.source, fixture.layout, EmptyBindingSet.getInstance());
			try {
				assertTrue(iteration.initialize(row), aggregateName + " input is admitted before order inspection");
				assertNull(fixture.plan.statementOrder,
						"the scan has no explicit ordered request that would bind index metadata to its cursor");
				assertEquals("spoc", fixture.source.indexName(-1L, 9L, -1L, 0L),
						"the source advertises an SP-order index as an ordinary fallback candidate");

				row.encounterOrderRequired = true;
				List<Long> openedGroups = new ArrayList<>();
				try (RowCursor cursor = fixture.plan.open(row)) {
					while (row.advance(cursor)) {
						openedGroups.add(row.slots[0]);
					}
				}
				assertEquals(List.of(100L, 101L, 100L, 101L, 100L, 101L, 100L, 101L), openedGroups,
						"the admitted encounter-order cursor interleaves groups despite the fallback index name");
				assertEquals(8, fixture.reads.get(), "the order control observes every admitted source row");

				NativeAggregateDistinctPlan current = LmdbNativeOrderPlanner.aggregateInCurrentOrder(fixture.plan,
						new int[] { 0 }, specs, row);
				assertAll(aggregateName + " must not infer a current-order grouping proof from a fallback index name",
						() -> assertFalse(LmdbNativeOrderPlanner.completeGroupPrefix(current, new int[] { 0 }),
								"interleaved groups do not have a complete contiguous prefix"),
						() -> assertNull(NativeGroupResultCursor.orderedPlan(iteration, row),
								"ordered aggregation must decline when only fallback metadata matches the group key"),
						distinctChannel
								? () -> assertEquals(NativeDistinctChannelMode.HASH, current.channels.modes[0],
										"floating SUM cannot reuse a false monotonic DISTINCT channel")
								: () -> assertEquals(0, current.channels.channelCount()));
				assertImplicitFallbackOrderRemainsUnknownThroughAliasesAndMandatorySpines(fixture, specs);
			} finally {
				row.closeDecodedInputs();
				iteration.close();
			}
		}
	}

	private static void assertImplicitFallbackOrderRemainsUnknownThroughAliasesAndMandatorySpines(Fixture fixture,
			AggregateSpec[] specs) {
		SlotPlan alias = new ExtensionPlan(fixture.plan, new CopyBinding[] { CopyBinding.slot(2, 0) });
		SlotPlan mandatorySpine = new JoinPlan(SingletonPlan.INSTANCE,
				new FilterPlan(alias, ignored -> true, 1L << 2));
		RowState row = new RowState(fixture.source, fixture.layout, EmptyBindingSet.getInstance());
		try {
			assertTrue(SlotPlan.encounterOrderReplaySafe(alias),
					"the alias copy is a supported replay-safe plan, so unknown order must come from its producer");
			assertTrue(SlotPlan.encounterOrderReplaySafe(mandatorySpine),
					"the singleton Join and row-local Filter are supported mandatory wrappers");
			NativeAggregateDistinctPlan aliased = LmdbNativeOrderPlanner.aggregateInCurrentOrder(alias,
					new int[] { 2 }, specs, row);
			NativeAggregateDistinctPlan composed = LmdbNativeOrderPlanner.aggregateInCurrentOrder(mandatorySpine,
					new int[] { 2 }, specs, row);
			assertAll("fallback index metadata cannot become a grouping proof through aliases or mandatory wrappers",
					() -> assertFalse(LmdbNativeOrderPlanner.completeGroupPrefix(aliased, new int[] { 2 }),
							"an Extension alias must preserve the absence of an opened-cursor order proof"),
					() -> assertFalse(LmdbNativeOrderPlanner.completeGroupPrefix(composed, new int[] { 2 }),
							"a mandatory singleton Join and row-local Filter must preserve unknown input order"));
		} finally {
			row.closeDecodedInputs();
		}
	}

