	@Test
	void aDirectPhysicalWitnessReleasesItsAggregateOwnerBeforeTheSource() throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(2L << 20, 2L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		try (Fixture fixture = fixture()) {
			NativeExecutionContext sourceContext = fixture.source.executionContext();
			LmdbQueryMemoryManager.QueryLedger ledger = sourceContext.memoryLedger();
			Literal sourceOwned = SimpleValueFactory.getInstance().createLiteral("source-owned-baseline");
			long sourceOwnedId = fixture.source.internComputedValue(sourceOwned);
			assertEquals(sourceOwned, fixture.source.lazyValue(sourceOwnedId),
					"the source baseline must retain a round-trippable generated RDF term");
			long sourceBaseline = ledger.usedBytes();
			assertTrue(sourceBaseline > 0L, "the independent source owner must hold a measurable baseline");

			SingletonSet target = telemetryTarget();
			NativeGroupStep boundary = step(fixture, lexicalLengthSpecs(), target, null);
			NativePhysicalResultPlan selected = boundary.physicalPlan(EmptyBindingSet.getInstance());
			assertNotNull(selected, "the admitted summary witness must produce an executable physical plan");
			assertEquals(sourceBaseline, ledger.usedBytes(),
					"planning must release its temporary aggregate owner before opening the selected result");

			NativeResultCursor cursor = ((NativeResultStep) selected.step())
					.evaluateNative(EmptyBindingSet.getInstance());
			long liveBytes;
			try {
				NativeResultRow first = cursor.next();
				assertNotNull(first, "the direct witness must produce its first admitted group");
				assertEquals(NativeResultCell.Kind.LEXICAL_SUMMARY, first.cell("length").kind());
				assertEquals(4L, first.cell("length").codePointLength());
				liveBytes = ledger.usedBytes();
			} finally {
				cursor.close();
			}
			assertTrue(liveBytes > sourceBaseline,
					"the open result's aggregate context must own positive query-ledger bytes");
			assertFalse(sourceContext.isClosed(), "closing the direct result must leave its outer source alive");
			assertEquals(sourceBaseline, ledger.usedBytes(),
					"closing a directly selected witness must release its own aggregate workspace immediately");
			sourceContext.close();
			assertEquals(0L, manager.usedBytes(),
					"closing the independent source owner releases its retained generated term");
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
		}
	}

