	@Test
	void cancelledBoundedReducerReadDeletesItsExactPayloadSpill() throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		String previousGroupLimit = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		String previousGroupsEnabled = System.getProperty(NativeCountGroupStore.ENABLED_PROPERTY);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(8L << 20, 8L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "16384");
		System.setProperty(NativeCountGroupStore.ENABLED_PROPERTY, "true");
		try (Fixture fixture = fixture()) {
			NativeExecutionContext sourceContext = fixture.source.executionContext();
			LmdbQueryMemoryManager.QueryLedger ledger = sourceContext.memoryLedger();
			NativeSlotLayout layout = new NativeSlotLayout(Map.of("sample", 0), null);
			layout.freeze(List.of("sample"));
			var factory = SimpleValueFactory.getInstance();
			TripleTerm payload = factory.createTripleTerm(factory.createIRI("urn:cancel:subject"),
					factory.createIRI("urn:cancel:predicate"), factory.createLiteral("🧭".repeat(9_000), "ar",
							Literal.BaseDirection.RTL));
			long payloadId = internExact(fixture.source, payload);
			long sourceBaseline = ledger.usedBytes();
			long spillsBefore = NativeBoundedReducerValues.SPILL_FILES_CREATED.get();
			long deletesBefore = NativeBoundedReducerValues.SPILL_FILES_DELETED.get();
			AggregateSpec[] specs = { AggregateSpec.slot("sample", 0, false, AggKind.SAMPLE) };
			AggContext context = new AggContext(fixture.source, true);
			AggState state = AggState.bounded(specs, 0, context, AggregateDistinctChannels.sequential(specs),
					context.cancellation, ledger);
			RowState row = aggregateValueRow(fixture.source, layout, payloadId);
			try {
				state.add(row);
				row.closeDecodedInputs();
				context.close();
				assertTrue(NativeBoundedReducerValues.SPILL_FILES_CREATED.get() > spillsBefore,
						"the admitted large RDF-star payload must spill before cancellation is requested");
				context.cancellation.requestCancellation();
				assertThrows(KernelQueryCancelledException.class, () -> state.extremeValue(0),
						"a cancelled payload read must remain terminal rather than publish a partial result");
			} finally {
				row.closeDecodedInputs();
				state.closeExternal();
				context.close();
			}
			assertEquals(NativeBoundedReducerValues.SPILL_FILES_CREATED.get() - spillsBefore,
					NativeBoundedReducerValues.SPILL_FILES_DELETED.get() - deletesBefore,
					"cancellation cleanup deletes each bounded reducer spill exactly once");
			assertEquals(sourceBaseline, ledger.usedBytes(),
					"cancelled reducer cleanup releases its payload without closing the source owner");
			sourceContext.close();
			assertEquals(0L, manager.usedBytes(), "closing the source releases the remaining admitted RDF term");
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
			restoreProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, previousGroupLimit);
			restoreProperty(NativeCountGroupStore.ENABLED_PROPERTY, previousGroupsEnabled);
		}
	}

	@Test
	void replacingOneSpilledReducerPayloadKeepsItsOwnedFileBounded() throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		String previousGroupLimit = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		String previousGroupsEnabled = System.getProperty(NativeCountGroupStore.ENABLED_PROPERTY);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(8L << 20, 8L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "16384");
		System.setProperty(NativeCountGroupStore.ENABLED_PROPERTY, "true");
		try (Fixture fixture = fixture()) {
			NativeExecutionContext sourceContext = fixture.source.executionContext();
			LmdbQueryMemoryManager.QueryLedger ledger = sourceContext.memoryLedger();
			long sourceBaseline = ledger.usedBytes();
			long spillsBefore = NativeBoundedReducerValues.SPILL_FILES_CREATED.get();
			long deletesBefore = NativeBoundedReducerValues.SPILL_FILES_DELETED.get();
			Map<Path, Long> filesBefore = reducerSpillSizes();
			AggContext context = new AggContext(fixture.source, true);
			NativeBoundedReducerValues values = new NativeBoundedReducerValues(1, context, context.cancellation,
					ledger);
			Path ownedSpill = null;
			long firstSpillBytes = -1L;
			try {
				var factory = SimpleValueFactory.getInstance();
				for (int replacement = 0; replacement < 16; replacement++) {
					String suffix = String.format(Locale.ROOT, "%08d", replacement);
					Literal payload = factory.createLiteral("typed-" + suffix + "-" + "λ🧭漢字😀".repeat(8_192), "ar",
							Literal.BaseDirection.RTL);
					TripleTerm exact = factory.createTripleTerm(factory.createIRI("urn:spill-replacement:subject"),
							factory.createIRI("urn:spill-replacement:predicate"), payload);
					values.set(0, exact);
					assertEquals(exact, values.get(0),
							"each overwritten record must still decode the exact nested RDF term");
					Map<Path, Long> liveFiles = reducerSpillSizes();
					List<Path> newFiles = liveFiles.keySet()
							.stream()
							.filter(path -> !filesBefore.containsKey(path))
							.toList();
					assertEquals(1, newFiles.size(), "one reducer owner creates one exact spill file");
					ownedSpill = newFiles.get(0);
					if (replacement == 0) {
						firstSpillBytes = liveFiles.get(ownedSpill);
					}
				}
				Map<Path, Long> finalFiles = reducerSpillSizes();
				assertEquals(1, finalFiles.size() - filesBefore.size(),
						"sixteen replacements retain one spill file owned by this reducer");
				long finalSpillBytes = finalFiles.get(ownedSpill);
				long observedFirstSpillBytes = firstSpillBytes;
				assertAll("replacing a single fixed reducer slot does not append every obsolete payload",
						() -> assertTrue(observedFirstSpillBytes > 0L,
								"the large typed payload must leave the resident budget"),
						() -> assertTrue(finalSpillBytes <= observedFirstSpillBytes + 64L,
								"the live file stays bounded by its current record and fixed codec framing"),
						() -> assertEquals(1L, NativeBoundedReducerValues.SPILL_FILES_CREATED.get() - spillsBefore,
								"all replacements are owned by one spill file"),
						() -> assertEquals(deletesBefore, NativeBoundedReducerValues.SPILL_FILES_DELETED.get(),
								"the current record remains owned until the reducer closes"),
						() -> assertTrue(ledger.usedBytes() > sourceBaseline,
								"the reducer owns its fixed spill workspace while the source remains open"));
			} finally {
				try {
					values.close();
				} finally {
					context.close();
				}
			}
			assertEquals(NativeBoundedReducerValues.SPILL_FILES_CREATED.get() - spillsBefore,
					NativeBoundedReducerValues.SPILL_FILES_DELETED.get() - deletesBefore,
					"all spill-file ownership is released exactly once on close");
			assertEquals(sourceBaseline, ledger.usedBytes(),
					"closing the reducer restores the source-only ledger baseline");
			assertNotNull(ownedSpill);
			assertFalse(Files.exists(ownedSpill), "the reducer removes its one owned spill after closing");
			sourceContext.close();
			assertEquals(0L, manager.usedBytes(), "source closure releases the remaining term authority");
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
			restoreProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, previousGroupLimit);
			restoreProperty(NativeCountGroupStore.ENABLED_PROPERTY, previousGroupsEnabled);
		}
	}

