	private static SlotPlan terminalFailureInput(Fixture fixture, RuntimeException failure,
			RuntimeException closeFailure,
			boolean cancellation, AtomicInteger advances, AtomicInteger closes) {
		return new SlotPlan() {
			@Override
			public RowCursor open(RowState row) {
				int entry = row.mark();
				return new RowCursor() {
					private boolean closed;

					@Override
					public boolean next() {
						advances.incrementAndGet();
						row.rollback(entry);
						if (cancellation) {
							row.cancellation.requestCancellation();
							throw KernelQueryCancelledException.INSTANCE;
						}
						throw failure;
					}

					@Override
					public void close() {
						if (!closed) {
							closed = true;
							closes.incrementAndGet();
							row.rollback(entry);
							if (closeFailure != null) {
								throw closeFailure;
							}
						}
					}
				};
			}

			@Override
			public long producedMask() {
				return 0L;
			}
		};
	}

	@Test
	void aQuotedWorkerRecipeKeepsItsSelectedChildAtActualOpen() throws Exception {
		try (Fixture fixture = fixture()) {
			fixture.source.executionContext().initializeQueryBase(EmptyBindingSet.getInstance());
			RowState quoteRow = seededEmptyRow(fixture.source, fixture.layout);
			AtomicInteger physicalQuotes = new AtomicInteger();
			Value selected = SimpleValueFactory.getInstance().createIRI("urn:physical-recipe:selected");
			Value reranked = SimpleValueFactory.getInstance().createIRI("urn:physical-recipe:reranked");
			NativeSubqueryPlan.WorkerFactory workerFactory = worker -> new NativeSubqueryPlan.BoundExecution(
					new RecipeSourceStep(physicalQuotes, selected, reranked), null, null);
			NativeSubqueryPlan plan = new NativeSubqueryPlan(
					new RecipeSourceStep(physicalQuotes, selected, reranked),
					new int[] { 2 }, new String[] { "opaque" }, new int[0], new String[0], new String[0],
					new String[0], null, null, workerFactory);
			NativeSubqueryPlan quoted = plan.withPhysicalPlan(quoteRow);
			assertNotNull(quoted, "the independent lexical child must produce an admitted concrete quote");
			assertEquals(1, physicalQuotes.get(), "initial quoting must select exactly one immutable child recipe");

			SyntheticValueSource workerSource = fixture.source.forInvocation(EmptyBindingSet.getInstance());
			workerSource.executionContext().initializeQueryBase(EmptyBindingSet.getInstance());
			RowState workerRow = null;
			String actualValue;
			try {
				workerRow = seededEmptyRow(workerSource, fixture.layout);
				NativeSubqueryPlan worker = quoted.forWorker(
						new NativeScalarPlan.WorkerContext(workerSource, null, null));
				try (RowCursor cursor = worker.open(workerRow)) {
					assertTrue(workerRow.advance(cursor), "the actual worker must open the quoted producer");
					actualValue = workerRow.view.getValue("opaque").stringValue();
					assertFalse(workerRow.advance(cursor), "the single bound lexical row is exhausted exactly once");
				}
			} finally {
				quoteRow.closeDecodedInputs();
				if (workerRow != null) {
					workerRow.closeDecodedInputs();
				}
				workerSource.executionContext().close();
			}
			assertAll("worker opening uses the original executable quote, not a fresh physical re-ranking",
					() -> assertEquals(1, physicalQuotes.get(),
							"worker binding must not ask for a different candidate"),
					() -> assertEquals(selected.stringValue(), actualValue,
							"the physical child selected at quote time must be the one opened by the worker"));
		}
	}

