	@Test
	void aRealGroupedPhysicalRecipeSurvivesTwoActualWorkerBinds(@TempDir Path directory) throws Exception {
		try (Fixture fixture = fixture()) {
			NativeExecutionContext query = fixture.source.executionContext();
			query.initializeQueryBase(EmptyBindingSet.getInstance());
			long expectedEvaluation = query.cancellation().evaluationId();
			long expectedOwner = query.cancellation().ownerThreadId();
			RowState quoteRow = seededEmptyRow(fixture.source, fixture.layout);
			try {
				AggregateSpec[] specs = lexicalLengthSpecs();
				String selectedFamily = LmdbNativeAttemptMetrics.PATH_ORDERED_DISTINCT_GROUPS;
				NativeGroupStep quotedGroup = step(fixture, specs, null, selectedFamily);
				AtomicInteger workerPreparations = new AtomicInteger();
				NativeSubqueryPlan.WorkerFactory factory = worker -> {
					SyntheticValueSource workerSource = (SyntheticValueSource) worker.source();
					Fixture prepared = new Fixture(workerSource, fixture.layout, fixture.plan, new AtomicInteger());
					workerPreparations.incrementAndGet();
					// The worker asks for a different family. A quoted recipe must retain the coordinator's selected
					// child.
					return new NativeSubqueryPlan.BoundExecution(
							step(prepared, specs, null, LmdbNativeAttemptMetrics.PATH_NESTED_LOOP), null, null);
				};
				NativeSubqueryPlan lexical = new NativeSubqueryPlan(quotedGroup, new int[] { 0, 2 },
						new String[] { "group", "length" }, new int[0], new String[0], new String[0], new String[0],
						null, null, factory);
				NativeSubqueryPlan quoted = lexical.withPhysicalPlan(quoteRow);
				assertNotNull(quoted, "the admitted grouped child must have one executable physical recipe");

				CountDownLatch ready = new CountDownLatch(2);
				CountDownLatch start = new CountDownLatch(1);
				List<String> expectedGroups = new ArrayList<>(FIXTURE_GROUPS);
				for (int group = 100; group < 100 + FIXTURE_GROUPS; group++) {
					expectedGroups.add(Integer.toString(group));
				}
				Path recordingPath = directory.resolve("grouped-physical-worker-rebind.jfr");
				try (Recording recording = new Recording(); ExecutorService workers = Executors.newFixedThreadPool(2)) {
					recording.enable(AGGREGATE_EVENT).withThreshold(Duration.ZERO);
					recording.start();
					Future<WorkerRows> first = workers.submit(
							() -> runQuotedGroupWorker(fixture, quoted, ready, start));
					Future<WorkerRows> second = workers.submit(
							() -> runQuotedGroupWorker(fixture, quoted, ready, start));
					try {
						assertTrue(ready.await(30, TimeUnit.SECONDS),
								"both dedicated worker threads must reach the gate");
					} finally {
						start.countDown();
					}
					WorkerRows firstRows = first.get(60, TimeUnit.SECONDS);
					WorkerRows secondRows = second.get(60, TimeUnit.SECONDS);
					recording.stop();
					recording.dump(recordingPath);
					assertNotEquals(firstRows.threadId(), secondRows.threadId(),
							"the two actual opens must run on distinct executor threads");
					assertAll("both real workers execute the same selected child recipe and typed result demand",
							() -> assertEquals(expectedGroups, firstRows.groups()),
							() -> assertEquals(expectedGroups, secondRows.groups()),
							() -> assertEquals(2, workerPreparations.get()));
				}
				List<jdk.jfr.consumer.RecordedEvent> opened = RecordingFile.readAllEvents(recordingPath)
						.stream()
						.filter(event -> AGGREGATE_EVENT.equals(event.getEventType().getName()))
						.filter(event -> "OPEN_RETURNED".equals(event.getString("outcome")))
						.toList();
				assertEquals(2, opened.size(), "each actual worker must open exactly one grouped aggregate recipe");
				assertAll("JFR identifies the concrete worker opens and inherited query owner",
						() -> assertEquals(Set.of(expectedEvaluation), opened.stream()
								.map(event -> event.getLong("evaluationId"))
								.collect(java.util.stream.Collectors.toSet())),
						() -> assertEquals(Set.of(expectedOwner), opened.stream()
								.map(event -> event.getLong("ownerThreadId"))
								.collect(java.util.stream.Collectors.toSet())),
						() -> assertEquals(Set.of(LmdbNativeAttemptMetrics.PATH_ORDERED_DISTINCT_GROUPS),
								opened.stream()
										.map(event -> event.getString("strategy"))
										.collect(java.util.stream.Collectors.toSet())),
						() -> assertEquals(Set.of("LEXICAL_LENGTH"), opened.stream()
								.map(event -> event.getString("resultDemands"))
								.collect(java.util.stream.Collectors.toSet())),
						() -> assertEquals(Set.of("STREAMING"), opened.stream()
								.map(event -> event.getString("retention"))
								.collect(java.util.stream.Collectors.toSet())));
				assertEquals(Set.of(Thread.currentThread().threadId()), Set.of(expectedOwner),
						"the explicit owner must be the query-entry thread, not either worker");
			} finally {
				quoteRow.closeDecodedInputs();
			}
		}
	}

	private static WorkerRows runQuotedGroupWorker(Fixture parent, NativeSubqueryPlan quoted,
			CountDownLatch ready, CountDownLatch start) throws Exception {
		long threadId = Thread.currentThread().threadId();
		ready.countDown();
		assertTrue(start.await(30, TimeUnit.SECONDS), "the worker gate must open after both threads are ready");
		SyntheticValueSource source = parent.source.forInvocation(EmptyBindingSet.getInstance());
		source.executionContext().initializeQueryBase(EmptyBindingSet.getInstance());
		RowState row = seededEmptyRow(source, parent.layout);
		List<String> groups = new ArrayList<>(FIXTURE_GROUPS);
		try {
			NativeSubqueryPlan worker = quoted.forWorker(NativeScalarPlan.WorkerContext.forSource(source, null));
			try (RowCursor cursor = worker.open(row)) {
				while (row.advance(cursor)) {
					groups.add(row.view.getValue("group").stringValue());
					NativeResultCell summary = row.summaryCell(2);
					assertNotNull(summary, "the lexical child must retain its typed summary lane in each worker");
					assertEquals(4L, summary.codePointLength(),
							"each source group has the same exact Unicode-aware distinct concatenation length");
				}
			}
		} finally {
			row.closeDecodedInputs();
			source.executionContext().close();
		}
		return new WorkerRows(threadId, List.copyOf(groups));
	}

	private record WorkerRows(long threadId, List<String> groups) {
	}

