	@Test
	void admittedPlanningContextClosesEveryOwnerAndKeepsTheSeedFailurePrimary() {
		QueryBindingSet bindings = new QueryBindingSet();
		bindings.addBinding("group", SimpleValueFactory.getInstance().createLiteral("admitted"));
		AtomicInteger admissionLookups = new AtomicInteger();
		AtomicInteger invocationSeedLookups = new AtomicInteger();
		AtomicBoolean invocationStarted = new AtomicBoolean();
		RuntimeException primary = new IllegalStateException("controlled later row-seed failure");
		RuntimeException cleanup = new IllegalStateException("tracked planning-owner cleanup failure");
		AtomicInteger throwingOwnerCloses = new AtomicInteger();
		AtomicInteger laterOwnerCloses = new AtomicInteger();
		AtomicReference<NativeExecutionContext> planningContext = new AtomicReference<>();
		NativeLmdbQuerySource delegate = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		when(delegate.idSpace()).thenReturn(delegate);
		when(delegate.hasCanonicalIds()).thenReturn(true);
		when(delegate.idOf(any(Value.class), anyInt())).thenAnswer(call -> {
			if (invocationStarted.get()) {
				invocationSeedLookups.incrementAndGet();
				throw primary;
			}
			admissionLookups.incrementAndGet();
			return 17L;
		});
		TrackingInvocationSource source = new TrackingInvocationSource(delegate, planningContext,
				throwingOwnerCloses, laterOwnerCloses, cleanup, invocationStarted);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("group", 0, "value", 1, "opaque", 2), null);
		layout.freeze(List.of("group", "value", "opaque"));
		PatternPlan plan = new PatternPlan(Term.slot(0), Term.constant(9L), Term.slot(1), Term.constant(0L),
				ContextConstraint.UNRESTRICTED, false, "spoc", INPUT_ROWS);
		Fixture fixture = new Fixture(source, layout, plan, new AtomicInteger());
		NativeGroupStep step = step(fixture, lexicalLengthSpecs(), telemetryTarget(), null);

		assertTrue(NativeRowSeeder.supports(bindings, layout, source),
				"the direct entry binding must pass the ordinary native-admission proof");
		RuntimeException observed = assertThrows(IllegalStateException.class, () -> step.physicalPlan(bindings));
		NativeExecutionContext context = planningContext.get();
		assertNotNull(context, "forInvocation must have acquired the tracked planning owner before row seeding");
		AssertionError assertionFailure = null;
		try {
			assertAll("the failed planning path closes every acquired owner exactly once",
					() -> assertSame(primary, observed,
							"a later admitted row-seeding failure must remain primary during resource cleanup"),
					() -> assertTrue(admissionLookups.get() >= 1,
							"the external and physical-boundary admission checks must resolve the real entry binding"),
					() -> assertEquals(1, invocationSeedLookups.get(),
							"the controlled failure must occur on the later invocation-owned row seed"),
					() -> assertTrue(context.isClosed(), "the invocation query context must be closed after failure"),
					() -> assertEquals(1, throwingOwnerCloses.get(), "the failing owner close is attempted once"),
					() -> assertEquals(1, laterOwnerCloses.get(),
							"later native-state owners close after an earlier close fails"),
					() -> assertTrue(containsSuppressed(primary, cleanup),
							"cleanup failure is retained on the original seed failure"));
		} catch (AssertionError failure) {
			assertionFailure = failure;
		}
		RuntimeException testCleanupFailure = null;
		if (!context.isClosed()) {
			try {
				context.close();
			} catch (RuntimeException failure) {
				testCleanupFailure = failure;
			}
		}
		if (assertionFailure != null) {
			if (testCleanupFailure != null) {
				assertionFailure.addSuppressed(testCleanupFailure);
			}
			throw assertionFailure;
		}
		if (testCleanupFailure != null) {
			throw testCleanupFailure;
		}
	}

