	private static void add(NativeGroupTable table, RowState row, long group, long value) {
		int mark = row.mark();
		assertTrue(row.bind(0, group));
		assertTrue(row.bind(1, value));
		table.add(row);
		row.rollback(mark);
	}

	private static void preview(NativeGroupStep step, NativeGroupIteration iteration, RowState row,
			NativeExecutionContext executionContext) throws Exception {
		try (QueryExplanationContext ignored = QueryExplanationContext.enter(Explanation.Level.Optimized);
				NativeGroupResultCursor owner = new NativeGroupResultCursor(step, iteration, executionContext, false)) {
			NativePhysicalGroupArbitration.preview(step, owner, iteration, row);
		}
	}

	private static AggregateSpec[] lexicalLengthSpecs() {
		return new AggregateSpec[] { AggregateSpec.groupConcat("length", 1, true, "|")
				.withResultDemand(NativeAggregateResultDemand.LEXICAL_LENGTH) };
	}

	private static SingletonSet telemetryTarget() {
		SingletonSet target = new SingletonSet();
		target.setRuntimeTelemetryEnabled(true);
		return target;
	}

	private static JsonNode candidate(JsonNode quotes, String strategy) {
		if (quotes != null && quotes.isArray()) {
			for (JsonNode quote : quotes) {
				if (strategy.equals(quote.path("strategy").asString())) {
					return quote;
				}
			}
		}
		return null;
	}

	private static void assertKnownGroupingQuote(JsonNode quote, int rows) {
		assertEquals("ESTIMATED", quote.path("kind").asString());
		assertTrue(quote.path("physicalFeaturesKnown").asBoolean(),
				() -> "candidate quote must own its physical estimate: " + quote);
		assertTrue(quote.path("total").isObject(), () -> "candidate quote must include physical totals: " + quote);
		assertEquals((double) rows, quote.path("total").path("SCANNED_ROW").path("expected").asDouble());
		assertEquals((double) rows, quote.path("total").path("GROUP_UPDATE").path("expected").asDouble());
	}

	private static boolean hasFiniteKnownPhysicalQuote(JsonNode quote) {
		if (quote == null || !"ESTIMATED".equals(quote.path("kind").asString())
				|| !quote.path("physicalFeaturesKnown").asBoolean()) {
			return false;
		}
		JsonNode total = quote.path("total");
		if (!total.isObject() || total.size() == 0) {
			return false;
		}
		for (Map.Entry<String, JsonNode> entry : total.properties()) {
			JsonNode metric = entry.getValue();
			for (String bound : List.of("low", "expected", "high")) {
				JsonNode amount = metric.path(bound);
				if (!amount.isNumber() || !Double.isFinite(amount.asDouble())) {
					return false;
				}
			}
		}
		return true;
	}

	private static final class Fixture implements AutoCloseable {
		private final SyntheticValueSource source;
		private final NativeSlotLayout layout;
		private final PatternPlan plan;
		private final AtomicInteger reads;
		private final AtomicInteger closes;

		private Fixture(SyntheticValueSource source, NativeSlotLayout layout, PatternPlan plan, AtomicInteger reads) {
			this(source, layout, plan, reads, new AtomicInteger());
		}

		private Fixture(SyntheticValueSource source, NativeSlotLayout layout, PatternPlan plan, AtomicInteger reads,
				AtomicInteger closes) {
			this.source = source;
			this.layout = layout;
			this.plan = plan;
			this.reads = reads;
			this.closes = closes;
		}

		@Override
		public void close() {
			source.executionContext().close();
		}
	}
